#[derive(Clone, Copy, Debug, PartialEq)]
#[repr(u16)]
pub enum Model136ReadOnly {
    Readwrite = 0,
    Readonly = 1,
}

impl Model136ReadOnly {
    pub fn from_repr(repr: u16) -> Option<Model136ReadOnly> {
        match repr {
            0 => Some(Model136ReadOnly::Readwrite),
            1 => Some(Model136ReadOnly::Readonly),
            _ => None,
        }
    }
}

/// Short, spec-matching alias for [`Model136ReadOnly`] - only `Model136ReadOnly` (unique per model) reaches the generated C header, since cbindgen has no module system to keep `ReadOnly` distinct from another model's point of the same name.
pub type ReadOnly = Model136ReadOnly;

